INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000241','DLG-00000025',1,'A','Hello. A table for two, please.','hello a table for two please',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000242','DLG-00000025',2,'B','Good evening. Do you have a booking?','good evening do you have a booking',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000243','DLG-00000025',3,'A','No, we don''t. Is that OK?','no we don t is that ok',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000244','DLG-00000025',4,'B','Yes, that''s fine. Inside or outside?','yes that s fine inside or outside',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000245','DLG-00000025',5,'A','Outside, please. It''s a nice evening.','outside please it s a nice evening',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000246','DLG-00000025',6,'B','Great. This way, please.','great this way please',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000247','DLG-00000026',1,'A','Hi. We have a booking. The name is Maya.','hi we have a booking the name is maya',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000248','DLG-00000026',2,'B','Hello, Maya. A table for five?','hello maya a table for five',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000249','DLG-00000026',3,'A','Yes. And we need a high chair, please.','yes and we need a high chair please',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000250','DLG-00000026',4,'B','Of course. We have one. Follow me.','of course we have one follow me',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000251','DLG-00000026',5,'A','Thank you. Is the table near the window?','thank you is the table near the window',NULL,NULL,'2026-09-22 01:12:48');
INSERT INTO utterances (utterance_id,dialogue_id,turn_no,speaker_role,text,normalized_text,intent_key,audio_id,created_at) VALUES ('UTT-00000252','DLG-00000026',6,'B','Yes, it is. Here you are.','yes it is here you are',NULL,NULL,'2026-09-22 01:12:48');
