-- Tiny ECW warehouse fixture for Tomorrow Mode tests: subset of the ecw-warehouse-db snapshot
-- (D04 ICU / Emergency room / Pharmacy, D05 Café / Restaurant). Read-only in tests.

CREATE TABLE domains (   domain_id TEXT PRIMARY KEY,   name TEXT NOT NULL UNIQUE,   description TEXT,   status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','RETIRED','REJECTED')),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE places (   place_id TEXT PRIMARY KEY,   domain_id TEXT NOT NULL,   name TEXT NOT NULL,   description TEXT,   status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','RETIRED','REJECTED')),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE(domain_id, name),   FOREIGN KEY (domain_id) REFERENCES domains(domain_id) );
CREATE TABLE situations (   situation_id TEXT PRIMARY KEY,   place_id TEXT NOT NULL,   name TEXT NOT NULL,   intent_key TEXT,   description TEXT,   status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','RETIRED','REJECTED')),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, intent_family_id TEXT REFERENCES intent_families(intent_family_id),   UNIQUE(place_id, name),   FOREIGN KEY (place_id) REFERENCES places(place_id) );
CREATE TABLE levels (   level_id TEXT PRIMARY KEY,   code TEXT NOT NULL UNIQUE,   sort_order INTEGER NOT NULL,   description TEXT,   active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)) );
CREATE TABLE scenarios (   scenario_id TEXT PRIMARY KEY,   situation_id TEXT NOT NULL,   level_id TEXT NOT NULL,   title TEXT NOT NULL,   primary_intent TEXT,   role_a TEXT NOT NULL,   role_b TEXT NOT NULL,   interaction_style TEXT,   conversation_goal TEXT,   suggested_turns INTEGER,   semantic_summary TEXT,   source_type TEXT NOT NULL DEFAULT 'SEED',   source_ref TEXT,   reuse_rights_status TEXT NOT NULL DEFAULT 'INTERNAL_OK' CHECK (reuse_rights_status IN ('UNKNOWN','INTERNAL_OK','COMMERCIAL_OK','RESTRICTED','BLOCKED')),   version_no INTEGER NOT NULL DEFAULT 1,   supersedes_id TEXT,   status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','RETIRED','REJECTED')),   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   approved_at TEXT,   retired_at TEXT,   change_reason TEXT,   FOREIGN KEY (situation_id) REFERENCES situations(situation_id),   FOREIGN KEY (level_id) REFERENCES levels(level_id),   FOREIGN KEY (supersedes_id) REFERENCES scenarios(scenario_id) );
CREATE TABLE dialogue_variants (   dialogue_id TEXT PRIMARY KEY,   scenario_id TEXT NOT NULL,   variant_no INTEGER NOT NULL,   variant_label TEXT,   audience_profile TEXT,   dialect_variant TEXT,   formality TEXT,   path_type TEXT DEFAULT 'STANDARD',   source_type TEXT NOT NULL,   source_ref TEXT,   generator_model TEXT,   generator_version TEXT,   qc_status TEXT NOT NULL DEFAULT 'PENDING' CHECK (qc_status IN ('PENDING','PASSED','FAILED','NEEDS_REVIEW')),   status TEXT NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','SUPERSEDED','RETIRED','REJECTED')),   version_no INTEGER NOT NULL DEFAULT 1,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   approved_at TEXT,   UNIQUE(scenario_id, variant_no),   FOREIGN KEY (scenario_id) REFERENCES scenarios(scenario_id) );
CREATE TABLE utterances (   utterance_id TEXT PRIMARY KEY,   dialogue_id TEXT NOT NULL,   turn_no INTEGER NOT NULL,   speaker_role TEXT NOT NULL CHECK (speaker_role IN ('A','B','SYSTEM')),   text TEXT NOT NULL,   normalized_text TEXT,   intent_key TEXT,   audio_id TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   UNIQUE(dialogue_id, turn_no),   FOREIGN KEY (dialogue_id) REFERENCES dialogue_variants(dialogue_id),   FOREIGN KEY (audio_id) REFERENCES audio_assets(audio_id) );
CREATE TABLE IF NOT EXISTS intent_families (intent_family_id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS audio_assets (audio_id TEXT PRIMARY KEY);
CREATE VIRTUAL TABLE scenario_fts USING fts5(   scenario_id UNINDEXED,   title,   primary_intent,   semantic_summary,   domain_name,   place_name,   situation_name,   tokenize = 'unicode61 remove_diacritics 2' );
CREATE VIEW v_servable_dialogues AS SELECT   dv.dialogue_id,   dv.scenario_id,   dv.variant_no,   dv.variant_label,   dv.audience_profile,   dv.formality,   dv.path_type,   s.title            AS scenario_title,   s.primary_intent,   s.role_a,   s.role_b,   si.situation_id,   si.name            AS situation_name,   p.place_id,   p.name             AS place_name,   d.domain_id,   d.name             AS domain_name,   l.level_id,   l.code             AS level_code,   (SELECT COUNT(*) FROM utterances u WHERE u.dialogue_id = dv.dialogue_id) AS turn_count FROM dialogue_variants dv JOIN scenarios  s  ON s.scenario_id   = dv.scenario_id JOIN situations si ON si.situation_id = s.situation_id JOIN places     p  ON p.place_id      = si.place_id JOIN domains    d  ON d.domain_id     = p.domain_id JOIN levels     l  ON l.level_id      = s.level_id WHERE dv.status    = 'ACTIVE'   AND dv.qc_status = 'PASSED'   AND s.status     = 'ACTIVE';
